source='''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    row_groups = {}
    col_groups = {}
    for r, c in points:
        row_groups.setdefault(r, []).append(c)
        col_groups.setdefault(c, []).append(r)
    candidates = []
    for r, cols in row_groups.items():
        if len(cols) >= 2:
            candidates.append((len(cols), max(cols) - min(cols), 'h', r, min(cols), max(cols)))
    for c, rows in col_groups.items():
        if len(rows) >= 2:
            candidates.append((len(rows), max(rows) - min(rows), 'v', c, min(rows), max(rows)))
    _, _, orientation, fixed, lo, hi = max(candidates)
    if orientation == 'h':
        for c in range(lo + 1, hi):
            if out[fixed][c] == 0:
                out[fixed][c] = 3
        for r, c in points:
            if r == fixed:
                continue
            step = 1 if r < fixed else -1
            for rr in range(r + step, fixed + step, step):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        for r in range(lo + 1, hi):
            if out[r][fixed] == 0:
                out[r][fixed] = 3
        for r, c in points:
            if c == fixed:
                continue
            step = 1 if c < fixed else -1
            for cc in range(c + step, fixed + step, step):
                if out[r][cc] == 0:
                    out[r][cc] = 3
    return out
'''
